mapper.update:
UPDATE forge_import_backup
SET imported_version=#{version},updated_at=CURRENT_TIMESTAMP,updated_by=NULL
WHERE NOT deleted AND task_id=#{taskId} AND record_id=#{recordId}

mapper.select:
SELECT id,task_id,record_id,CAST(field_values AS text) AS values_json,imported_version,expires_at
FROM forge_import_backup
WHERE NOT deleted AND task_id=#{taskId}
ORDER BY id LIMIT #{limit} OFFSET #{offset}
